<?php /* Template: Formal Transcript Certificate
   Paper: Legal */ $st = $doc['student']; ?>
<!doctype html><html><head><meta charset="utf-8"><title>Official Transcript – <?= e($st['name']) ?></title>
<?= doc_page_css('Legal', '12mm') ?><style>.doc-letterhead{border-bottom:3px double #222}.formal-title{text-align:center;margin:22px 0 15px}.formal-title strong{display:block;font-size:19px;letter-spacing:.09em}.formal-title span{font-size:12px}.bio{width:100%;border-collapse:collapse;margin:14px 0}.bio td{padding:5px 6px;border-bottom:1px solid #aaa}.bio .key{width:20%;font-weight:bold}.record-title{font-size:12px;font-weight:bold;margin:13px 0 4px;border-bottom:1px solid #333;padding-bottom:3px}.doc-table th{background:#eee!important}.statement{margin:16px 0;text-align:justify;line-height:1.5}.signature-row{display:flex;justify-content:space-between;align-items:end;gap:14px;margin-top:18px}
</style></head><body><div class="doc">
<?= doc_letterhead($doc) ?><div class="doc-control"><?= $doc['control_no'] ? 'Control no. ' . e($doc['control_no']) : '' ?></div>
<div class="formal-title"><strong>OFFICIAL TRANSCRIPT OF RECORDS</strong><span>ACADEMIC HISTORY</span></div>
<table class="bio"><tr><td class="key">Student name</td><td><strong><?= e(mb_strtoupper($st['name'])) ?></strong></td><td class="key">Student ID</td><td><?= e($st['id']) ?></td></tr><tr><td class="key">Program</td><td><?= e($st['program']) ?></td><td class="key">Standing</td><td><?= e($st['status']) ?></td></tr><tr><td class="key">Birth details</td><td><?= e(doc_date($st['birth_date'])) ?><?= $st['birth_place'] ? ' · ' . e($st['birth_place']) : '' ?></td><td class="key">Admitted</td><td><?= e(doc_date($st['date_admitted'])) ?></td></tr><tr><td class="key">Address</td><td colspan="3"><?= e($st['home_address']) ?></td></tr></table>
<?php if ($st['status'] === 'Graduated'): ?><p><strong>Graduation date:</strong> <?= e(doc_date($st['graduation_date'])) ?> &nbsp; <strong>Special Order no.:</strong> <?= e($st['so_number']) ?></p><?php endif; ?>
<?php foreach ($doc['periods'] as $p): ?><div class="record-title"><?= e($p['school_year']) ?><?= $p['term'] ? ' · ' . e($p['term']) : '' ?><?= $p['year_level'] ? ' · ' . e($p['year_level']) : '' ?> — <?= e($p['section']) ?></div><table class="doc-table"><thead><tr><th>Course code</th><th>Descriptive title</th><th class="n">Final grade</th><?php if ($doc['scale']['differs']): ?><th class="n">Equivalent<br>(<?= e($doc['scale']['final']) ?>)</th><?php endif; ?><th class="n">Units</th><th>Remarks</th></tr></thead><tbody>
<?php foreach ($p['subjects'] as $s): ?><tr><td><?= e($s['code']) ?></td><td><?= e($s['title']) ?></td><td class="n"><?= e($s['grade']) ?></td><?php if ($doc['scale']['differs']): ?><td class="n"><?= e($s['equivalent']) ?></td><?php endif; ?><td class="n"><?= e((float)$s['units']) ?></td><td><?= e($s['remarks']) ?></td></tr><?php endforeach; ?><tr><td colspan="2" class="n"><strong>Term average</strong></td><td class="n"><strong><?= e($p['gwa_text']) ?></strong></td><?php if ($doc['scale']['differs']): ?><td class="n"><?= e($p['equivalent_text']) ?></td><?php endif; ?><td class="n"><?= e((float)$p['units']) ?></td><td><?= e($p['remarks']) ?></td></tr></tbody></table><?php endforeach; ?>
<?php if (!$doc['periods']): ?><p><em>No final grades are recorded.</em></p><?php endif; ?><p class="statement"><strong>Academic summary:</strong> <?= e((float)$doc['totals']['units_earned']) ?> units earned; cumulative general weighted average <?= e($doc['totals']['gwa_text']) ?><?= $doc['totals']['equivalent_text'] ? ' (equivalent ' . e($doc['totals']['equivalent_text']) . ')' : '' ?>. <?= e($doc['totals']['remarks']) ?></p><?= doc_legend($doc) ?>
<p class="statement">This transcript is issued for <strong><?= e($doc['purpose'] ?: '________________') ?></strong>. *** End of record ***</p><div class="signature-row"><div>Prepared by<div class="doc-sign"><div class="line"><?= e($doc['signatories']['prepared_by'] ?: ' ') ?></div></div></div><div>Checked by<div class="doc-sign"><div class="line"><?= e($doc['signatories']['checked_by'] ?: ' ') ?></div></div></div><?= doc_signature($doc, 'Certified correct:') ?></div><?= doc_footer($doc) ?></div></body></html>
